parameters.jsCode:
// ⚙️ تنظیمات استراتژیک پیج و تقویم محتوایی
// اطلاعات زیر را متناسب با پیج خود شخصی‌سازی کنید:

return [{
  json: {
    // کلید API گوگل جمینای (می‌توانید مستقیم اینجا یا در Credentials ست کنید)
    gemini_api_key: "YOUR_GEMINI_API_KEY_HERE",

    // اطلاعات پیج اینستاگرام
    page_name: "آکادمی دیجی‌تک (DigiTech)",
    instagram_handle: "@amin.devv",
    niche: "آموزش فناوری، برنامه‌نویسی و ابزارهای هوش مصنوعی",
    description: "پیج آموزشی تخصصی برای معرفی ابزارهای جدید هوش مصنوعی، ترفندهای کاربردی و افزایش مهارت",
    target_audience: "دانشجویان، فریلنسرها، برنامه‌نویسان و علاقه‌مندان به تکنولوژی و پیشرفت",
    content_tone: "دوستانه، پرانرژی، کاربردی، سریع و بدون اصطلاحات سنگین خسته‌کننده",
    page_goals: ["افزایش فالوور", "تعامل بالا", "سیو و اشتراک‌گذاری", "برندینگ"],

    // پرامپت و استایل اختصاصی طراحی پوستر و ظاهر بصری
    poster_design: {
      custom_prompt: "پوستر مینیمال مدرن با پس‌زمینه دارک بلک مات، هایلایت‌های نئونی بنفش و فیروزه‌ای، تایپوگرافی بولد فارسی و المان شیشه‌ای",
      primary_color: "#ec4899",
      secondary_color: "#8b5cf6",
      style_theme: "cyber_neon",
      font_size_scale: "impact",
      show_page_id: true
    },

    // جدول تقویم محتوایی هفتگی (شنبه تا جمعه)
    weekly_calendar: [
      {
        day_of_week: "شنبه",
        topic: "آموزش تخصصی و ترفندهای سرعت عمل در نرم‌افزارها و کدنویسی",
        content_type: "Reel",
        goal: "جذب فالوور جدید با هوک میخکوب‌کننده ۳ ثانیه‌ای",
        details: "حل یک مشکل رایج که همه با آن دست‌وپنجه نرم می‌کنند"
      },
      {
        day_of_week: "یکشنبه",
        topic: "معرفی ۳ الی ۵ ابزار رایگان هوش مصنوعی جایگزین نرم‌افزارهای پولی",
        content_type: "Carousel",
        goal: "سیو و اشتراک‌گذاری حداکثری",
        details: "پست اسلایدی ورق‌زدنی با کاور کنجکاوکننده و اسلایدهای مرتب"
      },
      {
        day_of_week: "دوشنبه",
        topic: "پاسخ به سوالات پرتکرار مخاطبان و سناریوی تعاملی استوری",
        content_type: "Story",
        goal: "افزایش تعامل و صمیمیت با مخاطب",
        details: "استیکر نظرسنجی و کوییز برای بالا بردن ریپلای استوری"
      },
      {
        day_of_week: "سه‌شنبه",
        topic: "بررسی پرونده، اشتباهات خطرناک مبتدی‌ها یا مقایسه قبل و بعد",
        content_type: "Reel",
        goal: "اعتبار، مرجعیت و برندینگ فنی",
        details: "داستان‌سرایی و تجربه عملی همراه با مثال"
      },
      {
        day_of_week: "چهارشنبه",
        topic: "معرفی دوره، خدمات توسعه، پروژه یا پیشنهاد شگفت‌انگیز",
        content_type: "Post",
        goal: "فروش مستقیم و جذب لید و مشتری",
        details: "کال تو اکشن صریح دایرکت و لینک بیو"
      },
      {
        day_of_week: "پنج‌شنبه",
        topic: "چک‌لیست قدم‌به‌قدم هفتگی، خلاصه آموزش‌ها و نکات ضروری",
        content_type: "Carousel",
        goal: "سیو حداکثری برای رجوع دوباره",
        details: "چک‌لیست کاربردی که مخاطب حتماً ذخیره کند"
      },
      {
        day_of_week: "جمعه",
        topic: "پشت صحنه کاری، چالش‌های هفتگی و لایف‌استایل برنامه‌نویسی",
        content_type: "Story",
        goal: "وفاداری و ارتباط عاطفی با مخاطب",
        details: "حس خودمانی و آماده‌سازی برای شروع هفته قدرتمند"
      }
    ],

    // تنظیمات تلگرام (اختیاری جهت دریافت خروجی روی موبایل)
    telegram_bot_token: "YOUR_TELEGRAM_BOT_TOKEN_HERE",
    telegram_chat_id: "YOUR_TELEGRAM_CHAT_ID_HERE"
  }
}];

// تشخیص روز جاری به تقویم شمسی/هفته و استخراج برنامه همان روز
const config = $input.first().json;
const now = new Date();
const persianDays = ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنج‌شنبه', 'جمعه', 'شنبه'];
const todayPersianName = persianDays[now.getDay()];

// استخراج برنامه تقویم برای روز امروز
const dayPlan = config.weekly_calendar.find(p => p.day_of_week === todayPersianName) || config.weekly_calendar[0];

// ساخت پرامپت یکپارچه و استاندارد برای ارسال به Gemini AI
const systemInstruction = `تو یک مدیر ارشد استراتژی محتوا و اینستاگرامر حرفه‌ای (Instagram Growth Strategist) هستی.
وظیفه اصلی تو تولید دقیقاً یک سناریوی محتوایی کاربردی، جذاب و قابل اجرا برای پیج اینستاگرام بر اساس تقویم هفتگی کاربر است.
قوانین:
۱. ایده باید صددرصد منطبق بر موضوع، هدف و فرمت تعیین‌شده در تقویم محتوایی باشد.
۲. متن‌ها کاملاً به زبان فارسی روان، اصیل، جذاب و مدرن باشند.
۳. خروجی باید یک آبجکت JSON معتبر باشد.`;

const userPrompt = `اطلاعات پیج:
- نام پیج: ${config.page_name}
- آیدی: ${config.instagram_handle}
- حوزه فعالیت: ${config.niche}
- مخاطبان: ${config.target_audience}
- لحن: ${config.content_tone}

🗓️ تقویم محتوایی امروز (${todayPersianName}):
- موضوع مقرر: ${dayPlan.topic}
- فرمت: ${dayPlan.content_type}
- هدف: ${dayPlan.goal}
- نکات خاص: ${dayPlan.details}

🎨 دستورالعمل پرامپت طراحی پوستر و ظاهر بصری:
- پرامپت پوستر: ${config.poster_design.custom_prompt}
- رنگ اصلی: ${config.poster_design.primary_color}
- رنگ دوم: ${config.poster_design.secondary_color}
- سبک: ${config.poster_design.style_theme}
- نمایش آیدی: ${config.poster_design.show_page_id ? config.instagram_handle : 'خیر'}

لطفاً سناریوی کامل را به صورت یک آبجکت JSON شامل این فیلدها تولید کن:
- title (عنوان ایده)
- content_type (Reel, Story, Carousel, Post)
- goal (هدف محتوا)
- hook (هوک میخکوب‌کننده ۳ ثانیه اول)
- idea (توضیح هسته ایده)
- script (سناریوی گام‌به‌گام یا تایم‌لاین)
- video_script (متن دقیق کلامی ویدیو یا متن اسلایدها)
- caption (کپشن حرفه‌ای و کامل با ایموجی و فاصله‌بندی)
- cta (کال تو اکشن دقیق)
- visual_suggestion (پیشنهاد دقیق نور، قاب و طراحی پوستر بر اساس پرامپت طراحی کاربر)
- hashtags (آرایه‌ای از ۸ الی ۱۲ هشتگ استراتژیک فارسی)
- carousel_slides (اگر کاروسل است: آرایه‌ای از ۵ اسلاید با شماره، تیتر و متن)
- story_frames (اگر استوری است: آرایه‌ای از فریم‌ها با متن و نوع استیکر)
- reason (علت انتخاب این ایده برای رشد پیج)`;

return [{
  json: {
    ...config,
    today_day_name: todayPersianName,
    today_plan: dayPlan,
    system_instruction: systemInstruction,
    user_prompt: userPrompt
  }
}];

// پردازش و ساختاردهی خروجی هوش مصنوعی
const response = $input.first().json;
const previousData = $('تطبیق روز تقویم و ساخت پرامپت (Calendar Matcher)').first().json;

let content = {};
try {
  const rawText = response.candidates[0].content.parts[0].text;
  content = JSON.parse(rawText);
} catch (e) {
  throw new Error('خطا در تبدیل خروجی جمینای به JSON: ' + e.message);
}

// ساخت کپشن نهایی آماده انتشار
const hashtagsText = Array.isArray(content.hashtags) 
  ? content.hashtags.map(h => h.startsWith('#') ? h : '#' + h).join(' ')
  : '#تولید_محتوا #اینستاگرام #آموزش';

const formattedCaption = `${content.caption || ''}\n\n${content.cta ? '💡 ' + content.cta : ''}\n\n— — — — — — — — — —\n🆔 ${previousData.instagram_handle}\n\n${hashtagsText}`;

// قالب‌بندی پیام تلگرام
const telegramMessage = `✨ <b>ایده و سناریوی امروز اینستاگرام آماده شد!</b>\n\n` +
  `🗓️ <b>روز در تقویم:</b> ${previousData.today_day_name}\n` +
  `🎬 <b>فرمت:</b> ${content.content_type} | 🎯 <b>هدف:</b> ${content.goal}\n` +
  `📌 <b>عنوان ایده:</b> ${content.title}\n\n` +
  `⚡ <b>هوک شروع (۳ ثانیه اول):</b>\n«${content.hook}»\n\n` +
  `📝 <b>سناریوی اجرا:</b>\n${content.script}\n\n` +
  `🗣️ <b>متن کلامی یا اسلایدها:</b>\n${content.video_script}\n\n` +
  `🎨 <b>طراحی پوستر و کاور:</b>\n${content.visual_suggestion}\n\n` +
  `➖➖➖➖➖➖➖➖➖➖\n` +
  `📋 <b>کپشن آماده برای کپی:</b>\n<pre>${formattedCaption}</pre>`;

return [{
  json: {
    ...content,
    formatted_caption: formattedCaption,
    telegram_message: telegramMessage,
    telegram_chat_id: previousData.telegram_chat_id,
    telegram_bot_token: previousData.telegram_bot_token,
    generated_at: new Date().toISOString(),
    instagram_handle: previousData.instagram_handle
  }
}];

parameters.jsonBody:
={
  "chat_id": "{{ $json.telegram_chat_id }}",
  "text": {{ JSON.stringify($json.telegram_message) }},
  "parse_mode": "HTML",
  "reply_markup": {
    "inline_keyboard": [
      [
        {
          "text": "📲 باز کردن اینستاگرام برای انتشار",
          "url": "https://instagram.com/"
        }
      ]
    ]
  }
}
